130	  private Iterable<ReadWriteLock> bulkGetLock(Resource resource, Collection<String[]> keys) {
131	    Striped<ReadWriteLock> striped = stripedLockByResource.get(resource);
132	    List<Object> lockKeys = new ArrayList<>(keys.size());
133	    for (String[] key : keys) {
134	      if (Objects.nonNull(key)) {
135	        lockKeys.add(CompositeKey.combineKeys(key));
136	      }
137	    }
138	    return striped.bulkGet(lockKeys);
139	  }
