141	  private ReentrantReadWriteLock getLock(Resource resource, String... keys) {
142	    Striped<ReadWriteLock> striped = stripedLockByResource.get(resource);
143	    Object key = combineKeys(keys);
144	    return (ReentrantReadWriteLock) striped.get(key);
145	  }
